    public static function key(string $s):string{return'member_card_'.substr(hash('sha256',$s),0,24);}
    public static function messages(string $locale):array{$en=explode('-',$locale,2)[0]==='en';$out=[];foreach(self::ENGLISH as$s=>$v)$out[self::key($s)]=$en?$v:$s;return$out;}
    public static function text(string $s,array $messages,array $values=[]):string
    {
        if(preg_match('/\AGültigkeit zwischen heute und ([0-9-]+) wählen\.\z/D',$s,$m)){$s='Gültigkeit zwischen heute und {date} wählen.';$values['date']=$m[1];}
        $s=$messages[self::key($s)]??ManagerMessages::text($s,$messages);foreach($values as$k=>$v)$s=str_replace('{'.$k.'}',(string)$v,$s);return$s;
    }
